local LocketMaker = {}
local PRODUCTS = {
    simple_silver_locket = { name = "Preprost srebrni medaljon", silverCost = 1, glassCost = 1, time = 4, cost = 60, beauty = 25, prestige = 4, happiness = 2, description = "Preprost srebrni medaljon za spomine." },
    engraved_gold_locket = { name = "Gravirani zlati medaljon", goldCost = 1, silverCost = 1, glassCost = 1, time = 7, cost = 180, beauty = 40, prestige = 10, happiness = 3, description = "Gravirani zlati medaljon za trgovce." },
    portrait_miniature_locket = { name = "Portretni miniaturni medaljon", goldCost = 1, silverCost = 1, glassCost = 1, paintCost = 1, time = 10, cost = 440, beauty = 55, prestige = 18, happiness = 4, description = "Portretni miniaturni medaljon za plemiče." },
    jewel_edged_locket = { name = "Draguljnorobni medaljon", goldCost = 2, silverCost = 1, glassCost = 1, paintCost = 1, jewelCost = 1, time = 14, cost = 1000, beauty = 70, prestige = 30, happiness = 5, description = "Medaljon z draguljnim robom za visoke plemiče." },
    pearl_set_locket = { name = "Bisernavi medaljon", goldCost = 2, silverCost = 1, glassCost = 1, paintCost = 1, jewelCost = 1, pearlCost = 1, time = 18, cost = 2200, beauty = 84, prestige = 45, happiness = 7, description = "Medaljon z biseri za visoko plemstvo." },
    royal_grand_locket = { name = "Kraljevski veliki medaljon", goldCost = 3, silverCost = 2, glassCost = 2, paintCost = 1, jewelCost = 2, pearlCost = 2, time = 25, cost = 4800, beauty = 95, prestige = 68, happiness = 13, description = "Veliki kraljevski medaljon z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    locket_workshop = { name = "Medaljonska delavnica", cost = { gold = 240, wood = 100, stone = 120, silver = 6, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    miniature_loft = { name = "Miniaturna podstrešje", cost = { gold = 920, wood = 240, stone = 240, silver = 6, paint = 6 }, upkeep = 21, qualityBonus = 18 },
    master_locket_atelier = { name = "Mojstrski medaljonski atelje", cost = { gold = 2600, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 60, qualityBonus = 30 },
    royal_locket_palace = { name = "Kraljevska medaljonska palača", cost = { gold = 11000, wood = 580, stone = 760, gold = 70, jewel = 18 }, upkeep = 220, qualityBonus = 55, prestigeBonus = 50 },
}
LocketMaker.silverStock = 10; LocketMaker.goldStock = 8; LocketMaker.glassStock = 12; LocketMaker.paintStock = 10; LocketMaker.jewelStock = 4; LocketMaker.pearlStock = 4
LocketMaker.productStock = {}; LocketMaker.buildings = {}; LocketMaker.maker = nil; LocketMaker.activeMaking = {}; LocketMaker.totalProducts = 0; LocketMaker.dayTimer = 0
function LocketMaker.init() LocketMaker.silverStock=10; LocketMaker.goldStock=8; LocketMaker.glassStock=12; LocketMaker.paintStock=10; LocketMaker.jewelStock=4; LocketMaker.pearlStock=4; LocketMaker.productStock={}; LocketMaker.buildings={}; LocketMaker.maker=nil; LocketMaker.activeMaking={}; LocketMaker.totalProducts=0; LocketMaker.dayTimer=0; print("[LocketMaker] Royal Locket Maker System initialized (6 products, 4 buildings)") end
function LocketMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; LocketMaker.maker={name=n or ("Medaljonar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Medaljonar najet: %s (spretnost: %d)",LocketMaker.maker.name,s),"success") end; return true end
function LocketMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function LocketMaker.build(id) local ok,e=LocketMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(LocketMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function LocketMaker.getQualityBonus() local b=0; for _,bd in ipairs(LocketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function LocketMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silverCost and LocketMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and LocketMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.glassCost and LocketMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.paintCost and LocketMaker.paintStock<(d.paintCost or 0) then return false,"Premalo barve" end; if d.jewelCost and LocketMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and LocketMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #LocketMaker.buildings==0 then return false,"Potrebna medaljonska delavnica" end; if not LocketMaker.maker then return false,"Potreben medaljonar" end; return true end
function LocketMaker.make(pt,qty) qty=qty or 1; local ok,e=LocketMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silverCost then LocketMaker.silverStock=LocketMaker.silverStock-d.silverCost*qty end; if d.goldCost then LocketMaker.goldStock=LocketMaker.goldStock-d.goldCost*qty end; if d.glassCost then LocketMaker.glassStock=LocketMaker.glassStock-d.glassCost*qty end; if d.paintCost then LocketMaker.paintStock=LocketMaker.paintStock-d.paintCost*qty end; if d.jewelCost then LocketMaker.jewelStock=LocketMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then LocketMaker.pearlStock=LocketMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if LocketMaker.maker then t=math.max(1,t-math.floor(LocketMaker.maker.skill/13)) end; table.insert(LocketMaker.activeMaking,{id="locket_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function LocketMaker.completeMaking(m) local q=1.0+(LocketMaker.getQualityBonus()/100); if LocketMaker.maker then q=q+(LocketMaker.maker.skill/140) end; q=math.min(2.5,q); LocketMaker.productStock[m.productType]=(LocketMaker.productStock[m.productType] or 0)+m.quantity; LocketMaker.totalProducts=LocketMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if LocketMaker.maker then LocketMaker.maker.itemsMade=LocketMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then LocketMaker.maker.skill=math.min(100,LocketMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Medaljon izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"locket.completed",{productName=m.productName,beauty=m.beauty,prestige=m.prestige,happiness=m.happiness}) end end
function LocketMaker.update(dt) if not _G.state then return end; LocketMaker.dayTimer=LocketMaker.dayTimer+dt; if LocketMaker.dayTimer>=30 then LocketMaker.dayTimer=0; for i=#LocketMaker.activeMaking,1,-1 do local m=LocketMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then LocketMaker.completeMaking(m); table.remove(LocketMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(LocketMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if LocketMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function LocketMaker.getStats() return {silverStock=LocketMaker.silverStock,goldStock=LocketMaker.goldStock,glassStock=LocketMaker.glassStock,paintStock=LocketMaker.paintStock,jewelStock=LocketMaker.jewelStock,pearlStock=LocketMaker.pearlStock,productStock=LocketMaker.productStock,numBuildings=#LocketMaker.buildings,hasMaker=LocketMaker.maker~=nil,makerName=LocketMaker.maker and LocketMaker.maker.name or "—",makerSkill=LocketMaker.maker and LocketMaker.maker.skill or 0,activeMaking=#LocketMaker.activeMaking,totalProducts=LocketMaker.totalProducts} end
return LocketMaker
